function BROWN_CENSUS(bound):
    fact <- 1
    result <- empty list
    for n from 0 to bound-1:
        if n > 0: fact <- fact * n      # fact = n!
        cand <- fact + 1
        r <- ISQRT(cand)                # largest r with r*r <= cand
        if r * r == cand:
            append n to result
    return result

